import { SeedTsPaginationNestedBodyClient } from "@fern/ts-pagination-nested-body";

const client = new SeedTsPaginationNestedBodyClient({ baseUrl: "YOUR_BASE_URL" });
const pageableResponse = await client.users.listWithNestedOffset({
    filter: "active"
});
for await (const item of pageableResponse) {
    console.log(item);
}

// Or you can manually iterate page-by-page
let page = await client.users.listWithNestedOffset({
    filter: "active"
});
while (page.hasNextPage()) {
    page = await page.getNextPage();
}

// You can also access the underlying response
const response = page.response;

